  id: string & tags.Format<"uuid">;

  /** Summary of the list the invitation targets. */
  list: ITodoAppListSummary;

  /**
   * Summary of the user who issued the invitation. Maps to
   * inviter_todouser_id (non-nullable).
   */
  inviter: ITodoAppUserSummary;

  /**
   * Invitation lifecycle state
   * ('pending','accepted','declined','expired','revoked').
   */
  state: string;

  /**
   * Opaque invite token (todo_app_invitations.invite_code). SENSITIVE:
   * included only when the caller is the list owner or the invitee; for other
   * authorized viewers the field MUST be returned as null or omitted by the
   * API layer. Do NOT log or leak this token in unsecured channels.
   */
  inviteCode?: string | null | undefined;

  /**
   * If the invite targets a registered user, the invitee summary. Maps to
   * invitee_todouser_id (nullable).
   */
