  /**
   * Email used for invitation when invitee not registered. Nullable per
   * Prisma (todo_app_invitations.invitee_email). For privacy, servers SHOULD
   * omit or redact this field for callers who are not the owner or the
   * invitee.
   */
  inviteeEmail?: (string & tags.Format<"email">) | null | undefined;

  /**
   * Expiration timestamp for the invitation (maps to
   * todo_app_invitations.expires_at in the Prisma schema).
   */
  expiresAt: string & tags.Format<"date-time">;

  /**
   * When the invitation was accepted (nullable). Maps to
   * todo_app_invitations.accepted_at.
   */
  acceptedAt?: (string & tags.Format<"date-time">) | null | undefined;

  /**
   * Creation timestamp for the invitation (maps to
   * todo_app_invitations.created_at).
   */
  createdAt: string & tags.Format<"date-time">;

  /**
   * Last update timestamp for the invitation (maps to
   * todo_app_invitations.updated_at).
   */
  updatedAt: string & tags.Format<"date-time">;
